import * as React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import info from "../data/data.json";
import SEO from "../components/seo";
import Layout from "../components/layout";
import { AuditRequestButton } from "../components/auditRequestModal";
import { trackEvent } from "../utils/analytics";
import {
  featuredCaseStudyKeys,
  caseStudySlugs,
  mapLiveProjectsWithImages,
  projectRelatedServiceKeys,
  type LivePortfolioProject,
  type LivePortfolioProjectWithImages,
} from "../utils/livePortfolio";
import type {
  ArchivePortfolioProject,
} from "../components/archivePortfolioGrid";

type Filter = "all" | "featured" | "live" | "archive";

// ── Arrow icon
function ArrowIcon() {
  return (
    <svg className="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
      <path d="M5 12h14M13 5l7 7-7 7" />
    </svg>
  );
}

// ── Featured project color palette
const featColors: Record<string, { a: string; b: string }> = {
  envirogun:       { a: "oklch(0.62 0.18 40)",  b: "oklch(0.82 0.13 80)" },
  chestercourt:    { a: "oklch(0.25 0.03 60)",  b: "oklch(0.62 0.18 40)" },
  jennyadventures: { a: "oklch(0.82 0.12 80)",  b: "oklch(0.62 0.18 40)" },
  reef:            { a: "oklch(0.55 0.12 220)", b: "oklch(0.85 0.06 200)" },
};

// ── Live grid color palette (index-based)
const liveColors = [
  { a: "oklch(0.7 0.12 120)",  b: "oklch(0.4 0.08 140)" },
  { a: "oklch(0.62 0.18 40)",  b: "oklch(0.25 0.05 40)" },
  { a: "oklch(0.85 0.09 90)",  b: "oklch(0.55 0.14 60)" },
  { a: "oklch(0.5 0.14 260)",  b: "oklch(0.82 0.08 240)" },
  { a: "oklch(0.3 0.02 60)",   b: "oklch(0.62 0.18 40)" },
  { a: "oklch(0.75 0.11 150)", b: "oklch(0.3 0.06 160)" },
  { a: "oklch(0.62 0.18 40)",  b: "oklch(0.92 0.04 80)" },
  { a: "oklch(0.4 0.08 310)",  b: "oklch(0.72 0.14 320)" },
  { a: "oklch(0.55 0.13 25)",  b: "oklch(0.85 0.08 60)" },
  { a: "oklch(0.2 0.02 60)",   b: "oklch(0.5 0.05 60)" },
  { a: "oklch(0.78 0.09 180)", b: "oklch(0.32 0.07 200)" },
  { a: "oklch(0.62 0.18 40)",  b: "oklch(0.25 0.03 60)" },
];

export default function PortfolioPage() {
  const { t } = useTranslation();
  const { language } = useI18next();
  const [filter, setFilter] = React.useState<Filter>("all");

  // ── Translation data
  const liveProjects = (t("portfolio.live.items", { returnObjects: true }) as LivePortfolioProject[]) || [];
  const archivedProjects = (t("portfolio.archive.items", { returnObjects: true }) as ArchivePortfolioProject[]) || [];
  const servicesItems = (t("services.items", { returnObjects: true }) as Array<{ key: string; title: string; href: string }>) || [];

  const liveProjectsWithImages = mapLiveProjectsWithImages(liveProjects) as LivePortfolioProjectWithImages[];
  const featuredProjects = liveProjectsWithImages.filter((p) =>
    featuredCaseStudyKeys.includes(p.imageKey as (typeof featuredCaseStudyKeys)[number])
  );
  const onlineProjects = liveProjectsWithImages.filter(
    (p) => !featuredCaseStudyKeys.includes(p.imageKey as (typeof featuredCaseStudyKeys)[number])
  );

  // ── Refs for scroll effects
  const timelineRef = React.useRef<HTMLDivElement>(null);
  const spineFillRef = React.useRef<HTMLDivElement>(null);

  // ── Spine fill animation
  React.useEffect(() => {
    const fill = spineFillRef.current;
    const spine = fill?.parentElement;
    if (!fill || !spine) return;

    let raf: number;
    function tick() {
      const rect = spine!.getBoundingClientRect();
      const prog = Math.min(Math.max((window.innerHeight * 0.5 - rect.top) / rect.height, 0), 1);
      fill!.style.height = `${prog * 100}%`;
      raf = requestAnimationFrame(tick);
    }
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, []);

  // ── Node highlight on scroll
  React.useEffect(() => {
    if (!timelineRef.current) return;
    const nodes = timelineRef.current.querySelectorAll(".tl-node");
    const io = new IntersectionObserver(
      (entries) => entries.forEach((en) => en.isIntersecting && en.target.classList.add("lit")),
      { rootMargin: "-40% 0px -40% 0px" }
    );
    nodes.forEach((n) => io.observe(n));
    return () => io.disconnect();
  }, [filter]);

  // ── Visibility helpers
  const show = (kind: "featured" | "live" | "archive") =>
    filter === "all" || filter === kind;

  return (
    <Layout data={info}>
      <main>

        {/* ======================================================
            HERO
        ====================================================== */}
        <section className="pf-hero shell">
          <div className="pf-hero-grid">
            <div className="pf-hero-meta">
              <div className="eyebrow">§ {t("portfolio.title")} · 2015 – 2026</div>
              <div className="mono muted" style={{ marginTop: "12px" }}>
                {featuredProjects.length} {t("portfolioPage.hero.counts.featured")} · {onlineProjects.length} {t("portfolioPage.hero.counts.online")} · {archivedProjects.length} {t("portfolioPage.hero.counts.archived")}
              </div>
            </div>

            <h1 className="display-xl pf-title" aria-label={t("portfolioPage.hero.title") as string}>
              {(t("portfolioPage.hero.displayLines", { returnObjects: true }) as string[]).map((line, i) => (
                <span key={line} className="reveal-line">
                  <span>{i === 1 ? <em className="italic">{line}</em> : line}</span>
                </span>
              ))}
            </h1>

            <p className="body-lg pf-intro reveal">{t("portfolioPage.hero.desc")}</p>

            <div className="pf-filters reveal">
              {(["all", "featured", "live", "archive"] as Filter[]).map((f) => (
                <button
                  key={f}
                  type="button"
                  className={`pf-filter${filter === f ? " active" : ""}`}
                  onClick={() => setFilter(f)}
                  aria-pressed={filter === f}
                >
                  {t(`portfolioPage.filters.${f}`)}
                </button>
              ))}
            </div>
          </div>
        </section>

        {/* ======================================================
            TIMELINE
        ====================================================== */}
        <section className="timeline-wrap shell">
          <div className="timeline" ref={timelineRef}>

            {/* Spine */}
            <div className="tl-spine" aria-hidden="true">
              <div className="tl-spine-fill" ref={spineFillRef} />
            </div>

            {/* ========== FEATURED ========== */}
            {show("featured") && (
              <div className="tl-section" data-kind="featured">
                <div className="tl-sec-label">
                  <span className="tl-sec-num">{t("portfolioPage.timeline.featured.num")}</span>
                  <span className="tl-sec-title">{t("portfolioPage.timeline.featured.title")}</span>
                </div>
              </div>
            )}

            {show("featured") && featuredProjects.map((project, i) => {
              const colors = featColors[project.imageKey] || { a: "oklch(0.62 0.18 40)", b: "oklch(0.82 0.10 55)" };
              const caseStudySlug = caseStudySlugs[project.imageKey];
              const relatedServices = (projectRelatedServiceKeys[project.imageKey] || [])
                .map((key) => servicesItems.find((s) => s.key === key))
                .filter((s): s is { key: string; title: string; href: string } => Boolean(s));

              return (
                <article key={project.imageKey} className="tl-item" data-year={project.year || "2024"}>
                  <div className="tl-node">
                    <span className="dot" />
                    {project.year && <span className="date mono">{project.year}</span>}
                  </div>

                  <div className="tl-card tilt">
                    <div className="tilt-inner">
                      {/* Card header */}
                      <div className="tl-card-top">
                        <div className="tl-tag accent mono">/{String(i + 1).padStart(2, "0")} · Featured</div>
                        <div className="mono muted">{project.stack}</div>
                      </div>

                      {/* Media */}
                      <div
                        className="tl-media"
                        style={{ "--a": colors.a, "--b": colors.b } as React.CSSProperties}
                      >
                        <img
                          src={project.images.large.src}
                          alt={project.images.large.alt || project.title}
                          style={{ width: "100%", height: "100%", objectFit: "cover" }}
                          decoding="async"
                        />
                      </div>

                      {/* Content */}
                      <div className="tl-content">
                        <div style={{ display: "flex", alignItems: "center", gap: "16px", marginBottom: "18px" }}>
                          <img
                            src={project.images.logo.src}
                            alt={project.images.logo.alt || `${project.title} logo`}
                            style={{ height: "36px", width: "auto" }}
                            decoding="async"
                          />
                          <h2 className="display-m">{project.title}</h2>
                        </div>

                        {project.note && <p className="body">{project.note}</p>}

                        {/* Challenge / Approach / Outcome */}
                        {project.useCase && (
                          <dl className="tl-facts">
                            <div>
                              <dt className="mono muted">{t("selectedProjects.labels.challenge")}</dt>
                              <dd>{project.useCase.challenge}</dd>
                            </div>
                            <div>
                              <dt className="mono muted">{t("selectedProjects.labels.approach")}</dt>
                              <dd>{project.useCase.approach}</dd>
                            </div>
                            <div>
                              <dt className="mono muted">{t("selectedProjects.labels.outcome")}</dt>
                              <dd>{project.useCase.outcome}</dd>
                            </div>
                          </dl>
                        )}

                        {/* Highlights as tags */}
                        <div className="tl-tags">
                          {project.highlights.slice(0, 5).map((h) => (
                            <span key={h} className="tag">{h}</span>
                          ))}
                        </div>

                        {/* Related services */}
                        {relatedServices.length > 0 && (
                          <div style={{ marginTop: "16px" }}>
                            <p className="mono muted" style={{ marginBottom: "8px", fontSize: "10px", letterSpacing: "0.14em", textTransform: "uppercase" }}>
                              {t("selectedProjects.labels.relatedServices")}
                            </p>
                            <div className="tl-tags">
                              {relatedServices.map((service) => (
                                <Link
                                  key={service.key}
                                  to={service.href}
                                  onClick={() => trackEvent("service_related_link_click", { source: "portfolio.timeline.relatedServices", project_name: project.title, service_key: service.key })}
                                  className="tag"
                                >
                                  {service.title}
                                </Link>
                              ))}
                            </div>
                          </div>
                        )}

                        {/* CTAs */}
                        <div style={{ display: "flex", flexWrap: "wrap", gap: "12px", marginTop: "28px" }}>
                          {caseStudySlug && (
                            <Link
                              to={`/${language}/portfolio/case-studies/${caseStudySlug}/`}
                              onClick={() => trackEvent("case_study_click", { source: "portfolio.timeline.caseStudy", project_name: project.title })}
                              className="btn btn-dark"
                            >
                              {t("caseStudy.viewCaseStudy")}
                              <ArrowIcon />
                            </Link>
                          )}
                          <a
                            href={project.href}
                            target="_blank"
                            rel="noreferrer"
                            onClick={() => trackEvent("portfolio_click", { source: "portfolio.timeline.visit", project_name: project.title, target_url: project.href })}
                            className="btn btn-ghost"
                          >
                            {t("selectedProjects.labels.visitSite")}
                          </a>
                        </div>
                      </div>
                    </div>
                  </div>
                </article>
              );
            })}

            {/* ========== LIVE GRID ========== */}
            {show("live") && (
              <div className="tl-section" data-kind="live">
                <div className="tl-sec-label">
                  <span className="tl-sec-num">{t("portfolioPage.timeline.live.num")}</span>
                  <span className="tl-sec-title">{t("portfolioPage.timeline.live.title")}</span>
                  <span className="mono muted" style={{ marginLeft: "auto" }}>{onlineProjects.length} {t("portfolioPage.sections.live.title").toLowerCase()}</span>
                </div>
              </div>
            )}

            {show("live") && (
              <div className="tl-grid-item">
                <div className="tl-node"><span className="dot small" /></div>
                <div className="tl-live-grid">
                  {onlineProjects.map((project, i) => {
                    const colors = liveColors[i % liveColors.length];
                    return (
                      <a
                        key={project.imageKey}
                        href={project.href}
                        target="_blank"
                        rel="noreferrer"
                        className="tl-live tilt"
                        data-hover
                        onClick={() => trackEvent("portfolio_click", { source: "portfolio.timeline.live", project_name: project.title, target_url: project.href })}
                      >
                        <div className="tilt-inner">
                          <div className="tl-live-num">{String(featuredProjects.length + i + 1).padStart(2, "0")}</div>
                          <div
                            className="tl-live-thumb"
                            style={{ "--a": colors.a, "--b": colors.b } as React.CSSProperties}
                          >
                            <img
                              src={project.images.large.src}
                              alt={project.images.large.alt || project.title}
                              style={{ width: "100%", height: "100%", objectFit: "cover", borderRadius: "10px" }}
                              decoding="async"
                            />
                          </div>
                          <h3 className="display-s">{project.title}</h3>
                          <div className="mono muted">{project.role}</div>
                        </div>
                      </a>
                    );
                  })}
                </div>
              </div>
            )}

            {/* ========== ARCHIVE ========== */}
            {show("archive") && (
              <div className="tl-section" data-kind="archive">
                <div className="tl-sec-label">
                  <span className="tl-sec-num">{t("portfolioPage.timeline.archive.num")}</span>
                  <span className="tl-sec-title">{t("portfolioPage.timeline.archive.title")}</span>
                  <span className="mono muted" style={{ marginLeft: "auto" }}>{archivedProjects.length} {t("portfolioPage.sections.archive.title").split(" ")[0].toLowerCase()}</span>
                </div>
              </div>
            )}

            {show("archive") && (
              <div className="tl-grid-item">
                <div className="tl-node"><span className="dot small" /></div>
                <ul className="tl-archive">
                  {archivedProjects.map((project, i) => (
                    <li key={project.title}>
                      <span className="mono num">{String(featuredProjects.length + onlineProjects.length + i + 1).padStart(2, "0")}</span>
                      <span className="ar-name">{project.title}</span>
                      <span className="ar-year mono muted">{project.year || "—"}</span>
                      <span className="ar-role mono muted">{project.role}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* ========== END MARKER ========== */}
            <div className="tl-end">
              <div className="tl-node"><span className="dot end" /></div>
              <div className="tl-end-text">
                <div className="eyebrow">§ {t("selectedProjects.cta.title").split(" ").slice(0, 2).join(" ")}</div>
                <h2 className="display-l">
                  <em className="italic">{t("portfolioPage.timeline.end")}</em>
                  {", "}
                  <span>{t("portfolioPage.timeline.endSub")}</span>
                </h2>
                <div className="tl-end-actions">
                  <AuditRequestButton
                    serviceName={t("contact.auditService") as string}
                    source="portfolio.timeline.end"
                    className="btn btn-dark"
                  >
                    {t("selectedProjects.labels.requestAudit")}
                    <ArrowIcon />
                  </AuditRequestButton>
                  <Link
                    to={language === "fr" ? "/fr/services/" : "/en/services/"}
                    className="btn btn-ghost"
                  >
                    {t("selectedProjects.labels.viewAllServices")}
                  </Link>
                </div>
              </div>
            </div>

          </div>
        </section>

      </main>
    </Layout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

export const Head: HeadFC = ({ location, pageContext }) => {
  const language = (pageContext as { language?: string }).language || "fr";
  const pathname = language === "fr" ? "/fr/portfolio/" : "/en/portfolio/";
  const alternates = [
    { hrefLang: "fr", href: "https://riano.ca/fr/portfolio/" },
    { hrefLang: "en", href: "https://riano.ca/en/portfolio/" },
    { hrefLang: "x-default", href: "https://riano.ca/fr/portfolio/" },
  ];

  return (
    <SEO
      data={info}
      titleKey="seo.portfolio.metaTitle"
      descriptionKey="seo.portfolio.metaDescription"
      pathname={pathname}
      currentPathname={location.pathname}
      language={language}
      alternates={alternates}
      schemaType="ProfessionalService"
    />
  );
};
